-- TEST71 canonical product cost, FOC monthly analysis, and business push wiring.
create or replace function public.rr_upm_product_cost_actual_v703(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare c jsonb:=public.rr_upm_product_cost_actual_v679(p_canonical_lot_id,p_data_mode);l record;cut jsonb;bom jsonb;oldmat numeric:=coalesce((c->>'material_resolved_per_pc')::numeric,0);oldcut numeric:=coalesce((c->>'cutting_per_pc')::numeric,0);base numeric:=coalesce((c->>'actual_product_cost_raw_per_pc')::numeric,0);newcut numeric;bomraw numeric;box numeric:=0;raw numeric;app numeric;margin numeric:=coalesce((c->>'owner_margin_per_pc')::numeric,0);begin select * into l from public.rr_upm_lot_registry where canonical_lot_id=p_canonical_lot_id;cut:=public.rr_costing_cutting_rate_v649(p_canonical_lot_id);newcut:=coalesce((cut->>'cost_per_pc')::numeric,0);bom:=public.rr_bom_material_aggregate_v701(p_canonical_lot_id,p_data_mode);bomraw:=coalesce((bom->>'raw_bom_per_pc')::numeric,0);box:=public.rr_costing_box_cost_per_pc_v259(l.lot_no);raw:=greatest(base-oldmat-oldcut+newcut+bomraw+box,0);app:=round(raw,2);return c||jsonb_build_object('version','V703_CANONICAL_RAW_BOM_PRODUCT_COST','cutting_verified',cut,'bom_materials',bom,'legacy_material_fallback_removed_per_pc',oldmat,'canonical_raw_bom_per_pc',bomraw,'verified_cutting_per_pc',newcut,'packing_box_raw_per_pc',box,'packing_box_state',case when box>0 then 'ACTUAL_PACK_PLAN_BOUND' else 'PENDING_NOT_PACKED' end,'actual_product_cost_raw_per_pc',round(raw,6),'actual_product_cost_applicable_per_pc',app,'base_cost_per_pc',app,'final_sale_rate',public.rr_cost_final_rate_round_v675(app+margin));end $function$;
create or replace function public.rr_upm_product_cost_actual_v709(p_canonical_lot_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$ declare c jsonb:=public.rr_upm_product_cost_actual_v703(p_canonical_lot_id,p_data_mode);l record;f jsonb;raw numeric;app numeric;margin numeric:=coalesce((c->>'owner_margin_per_pc')::numeric,0);begin select * into l from public.rr_upm_lot_registry where canonical_lot_id=p_canonical_lot_id;if not found then raise exception 'Lot not found';end if;f:=public.rr_foc_cost_v705(coalesce(l.total_qty,0));raw:=coalesce((c->>'actual_product_cost_raw_per_pc')::numeric,0)+coalesce((f->>'total_rate_per_pc')::numeric,0);app:=round(raw,2);return c||jsonb_build_object('version','V709_FOC_PRODUCT_COST','foc',f,'foc_per_pc',f->'total_rate_per_pc','actual_product_cost_raw_per_pc',round(raw,6),'actual_product_cost_applicable_per_pc',app,'base_cost_per_pc',app,'final_sale_rate',public.rr_cost_final_rate_round_v675(app+margin),'foc_double_count_rule','ACTUAL WATER/ELECTRICITY/THREAD/REPAIRS/LAPSE ARE ANALYTICS ONLY; PRODUCT COST USES FOC ONCE');end $function$;
create or replace function public.rr_foc_monthly_analysis_v710(p_period_start date,p_data_mode text default 'REAL') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$ declare pe date:=(p_period_start+interval '1 month - 1 day')::date;pcs numeric;live jsonb;payroll_total numeric;productive numeric;lapse numeric;lapse_state text;elec numeric;water numeric;repairs numeric;thread_actual numeric;rows jsonb;begin select coalesce(sum(good_qty),0) into pcs from public.rr_upm_dynamic_submit_history_v741 where public.rr_costing_canonical_department_v760(department_code)='STITCHING' and submitted_at::date between p_period_start and pe;select sum(monthly_salary_amount) into payroll_total from public.rr_monthly_payroll_v779_1 where payroll_month=p_period_start and upper(data_mode)=upper(p_data_mode);select coalesce(sum(absorbed_salary),0) into productive from public.rr_salaried_team_session_v299 where status='COMPLETED' and ended_at::date between p_period_start and pe;if payroll_total is not null then lapse:=greatest(payroll_total-productive,0);lapse_state:='PAYROLL_ACTUAL';else live:=public.rr_costing_management_live_v677(pe,p_data_mode);lapse:=coalesce((live->>'lapse_salary_live_total_to_date')::numeric,0);lapse_state:='PROVISIONAL_UNTIL_PAYROLL';end if;select sum(amount) filter(where upper(expense_name) like '%ELECT%'),sum(amount) filter(where upper(expense_name) like '%WATER%'),sum(amount) filter(where upper(expense_name) like '%REPAIR%') into elec,water,repairs from public.rr_cost_expense_pool_v850 where upper(data_mode)=upper(p_data_mode) and is_active and period_start<=pe and period_end>=p_period_start;select sum(total_value) into thread_actual from public.rr_material_purchases_v805 where material_id='5c25e737-1d3d-4385-8b59-e72fbbe4ca1f' and upper(data_mode)=upper(p_data_mode) and bill_date between p_period_start and pe and bill_no<>'TEST71-E2E-PROVISION-OH-THREAD-CONE-202609';rows:=jsonb_build_array(jsonb_build_object('code','ELECTRICITY','recovered',round(pcs*1.5,2),'actual',elec,'state',case when elec is null then 'ACTUAL_PENDING' else 'READY' end,'gap',case when elec is null then null else round(pcs*1.5-elec,2) end),jsonb_build_object('code','THREAD','recovered',round(pcs*1.5,2),'actual',thread_actual,'state',case when thread_actual is null then 'ACTUAL_PENDING' else 'READY' end,'gap',case when thread_actual is null then null else round(pcs*1.5-thread_actual,2) end),jsonb_build_object('code','WATER','recovered',round(pcs*.5,2),'actual',water,'state',case when water is null then 'ACTUAL_PENDING' else 'READY' end,'gap',case when water is null then null else round(pcs*.5-water,2) end),jsonb_build_object('code','REPAIRS','recovered',round(pcs,2),'actual',repairs,'state',case when repairs is null then 'ACTUAL_PENDING' else 'READY' end,'gap',case when repairs is null then null else round(pcs-repairs,2) end),jsonb_build_object('code','LAPSE_SALARY','recovered',round(pcs,2),'actual',round(lapse,2),'state',lapse_state,'gap',round(pcs-lapse,2)));return jsonb_build_object('ok',true,'version','V710_FOC_MONTHLY_ANALYSIS','period_start',p_period_start,'period_end',pe,'eligible_pcs',pcs,'rows',rows,'total_recovered',round(pcs*5.5,2),'lapse_actual_state',lapse_state);end $function$;
create or replace function public.rr_foc_monthly_publish_v713(p_period_start date,p_data_mode text default 'REAL') returns jsonb language plpgsql security definer set search_path to 'public' as $function$ declare a jsonb:=public.rr_foc_monthly_analysis_v710(p_period_start,p_data_mode);r record;wid uuid;body text;route text:=public.rr_real_chat_route_v713('ACCOUNTS',null,'FOC');begin insert into public.rr_foc_monthly_summary_v706(period_start,data_mode,eligible_pcs,summary) values(p_period_start,upper(p_data_mode),coalesce((a->>'eligible_pcs')::numeric,0),a) on conflict(period_start,data_mode) do update set eligible_pcs=excluded.eligible_pcs,summary=excluded.summary,created_at=now();body:='FOC '||to_char(p_period_start,'Mon YYYY')||' · Recovered ₹'||coalesce(a->>'total_recovered','0')||' · Open report for actual vs recovery gaps.';for r in select id from public.rr_user_profiles where is_active and lower(role_code) in('owner','super_admin') loop wid:=public.rr_push_worker_id_v712(r.id);if wid is not null then insert into public.rr_targeted_push_outbox_v708(event_key,recipient_worker_id,title,body,route_url,payload) values('FOC_MONTHLY_V713:'||upper(p_data_mode)||':'||p_period_start::text,wid,'FOC Monthly Recovery Summary',body,route,a||jsonb_build_object('type','FOC_MONTHLY')) on conflict(event_key,recipient_worker_id) do nothing;end if;end loop;return jsonb_build_object('ok',true,'version','V713_FOC_ROUTE','analysis',a,'route_url',route);end $function$;
create or replace function public.rr_foc_monthly_cron_v711() returns jsonb language plpgsql security definer set search_path to 'public' as $function$ declare ps date:=(date_trunc('month',(now() at time zone 'Asia/Kolkata')::date)-interval '1 month')::date;begin perform public.rr_foc_monthly_publish_v713(ps,'REAL');return jsonb_build_object('ok',true,'period_start',ps,'version','V713');end $function$;
do $do$ declare jid bigint;begin select jobid into jid from cron.job where jobname='rr-foc-monthly-summary-v711';if jid is not null then perform cron.unschedule(jid);end if;perform cron.schedule('rr-foc-monthly-summary-v711','30 2 2 * *','select public.rr_foc_monthly_cron_v711();');end $do$;
